package com.jobworker.core

import java.util.concurrent.*
import java.util.concurrent.atomic.AtomicBoolean
import java.util.concurrent.atomic.AtomicReference
import java.util.concurrent.locks.ReentrantLock
import kotlin.concurrent.withLock

data class Job(val id: String, val payload: String, val priority: Int, val claimedBy: String? = null)

interface JobStore {
    fun fetchNextUnclaimed(workerId: String): Job?
    fun markClaimed(jobId: String, workerId: String): Boolean
    fun markCompleted(jobId: String, workerId: String): Boolean
    fun releaseClaim(jobId: String, workerId: String): Boolean
}

class InMemoryJobStore : JobStore {
    private val jobs = ConcurrentHashMap<String, Job>()
    private val claimLock = ReentrantLock()

    fun addJob(job: Job) { jobs[job.id] = job }

    override fun fetchNextUnclaimed(workerId: String): Job? {
        return jobs.values
            .filter { it.claimedBy == null }
            .maxByOrNull { it.priority }
    }

    override fun markClaimed(jobId: String, workerId: String): Boolean {
        claimLock.withLock {
            val job = jobs[jobId] ?: return false
            if (job.claimedBy != null) return false
            jobs[jobId] = job.copy(claimedBy = workerId)
            return true
        }
    }

    override fun markCompleted(jobId: String, workerId: String): Boolean {
        claimLock.withLock {
            val job = jobs[jobId] ?: return false
            if (job.claimedBy != workerId) return false
            jobs.remove(jobId)
            return true
        }
    }

    override fun releaseClaim(jobId: String, workerId: String): Boolean {
        claimLock.withLock {
            val job = jobs[jobId] ?: return false
            if (job.claimedBy != workerId) return false
            jobs[jobId] = job.copy(claimedBy = null)
            return true
        }
    }
}

class JobWorker(
    private val workerId: String,
    private val store: JobStore,
    private val executor: ExecutorService = Executors.newSingleThreadExecutor()
) {
    private val shutdownRequested = AtomicBoolean(false)
    private val currentJob = AtomicReference<Job?>(null)
    private val jobProcessingLock = ReentrantLock()
    private val shutdownComplete = CountDownLatch(1)

    fun start() {
        executor.submit { pollLoop() }
    }

    private fun pollLoop() {
        while (!shutdownRequested.get()) {
            try {
                val job = acquireJob()
                if (job != null) {
                    processJob(job)
                } else {
                    Thread.sleep(100)
                }
            } catch (e: InterruptedException) {
                Thread.currentThread().interrupt()
                break
            }
        }
        shutdownComplete.countDown()
    }

    private fun acquireJob(): Job? {
        val candidate = store.fetchNextUnclaimed(workerId) ?: return null
        // Set currentJob BEFORE claiming in store to ensure shutdown sees it
        currentJob.set(candidate)
        val claimed = store.markClaimed(candidate.id, workerId)
        if (!claimed) {
            currentJob.set(null)
            return null
        }
        return candidate
    }

    private fun processJob(job: Job) {
        jobProcessingLock.withLock {
            if (shutdownRequested.get()) {
                // Graceful: release the job back for other workers
                store.releaseClaim(job.id, workerId)
                currentJob.set(null)
                return
            }
            // Simulate processing
            Thread.sleep(50)
            store.markCompleted(job.id, workerId)
            currentJob.set(null)
        }
    }

    fun gracefulShutdown(timeoutMs: Long = 5000): Boolean {
        shutdownRequested.set(true)

        // Wait for current processing to finish
        val finished = shutdownComplete.await(timeoutMs, TimeUnit.MILLISECONDS)

        // Release any job that was acquired but not yet processed
        val pendingJob = currentJob.get()
        if (pendingJob != null) {
            store.releaseClaim(pendingJob.id, workerId)
            currentJob.set(null)
        }

        executor.shutdownNow()
        return finished
    }
}

class WorkerPool(
    private val store: JobStore,
    private val workerCount: Int = 4
) {
    private val workers = mutableListOf<JobWorker>()

    fun startAll() {
        repeat(workerCount) { i ->
            val worker = JobWorker("worker-$i", store)
            worker.start()
            workers.add(worker)
        }
    }

    fun shutdownAll(timeoutMs: Long = 5000): Boolean {
        return workers.all { it.gracefulShutdown(timeoutMs) }
    }
}
